package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
//
// The original implementation scanned the input one character at a time while
// juggling several pieces of shared state (the current header level, the list
// depth, an "inside a header" flag, ...). That made the control flow hard to
// follow. The parsing is actually line-oriented, so this version first applies
// the emphasis rules to the whole document and then renders it one line at a
// time. Each line is classified as a header, a list item, or a paragraph,
// which is much easier to read and produces identical output.
func Render(markdown string) string {
	var html strings.Builder
	listOpen := false

	closeList := func() {
		if listOpen {
			html.WriteString("</ul>")
			listOpen = false
		}
	}

	for _, line := range strings.Split(applyEmphasis(markdown), "\n") {
		if level, ok := headerLevel(line); ok {
			html.WriteString(renderHeader(level, line))
			continue
		}
		if isListItem(line) {
			if !listOpen {
				html.WriteString("<ul>")
				listOpen = true
			}
			html.WriteString("<li>" + line[2:] + "</li>")
			continue
		}
		// Any other line ends an open list and renders as a paragraph.
		closeList()
		html.WriteString("<p>" + line + "</p>")
	}
	closeList()
	return html.String()
}

// applyEmphasis converts the first "__" pair to <strong> and the first "_"
// pair to <em>. Like the original implementation it operates on the whole
// document rather than line by line.
func applyEmphasis(markdown string) string {
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	markdown = strings.Replace(markdown, "_", "</em>", 1)
	return markdown
}

// headerLevel reports the level of a header line, which is the number of
// leading "#". A line is a header when it starts with one to six "#"; a run
// of seven or more "#" is not a valid header level and is treated as a
// paragraph instead.
func headerLevel(line string) (int, bool) {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level < 1 || level > 6 {
		return 0, false
	}
	return level, true
}

// renderHeader renders a header line, dropping the leading "#" run and the
// single space that follows it.
func renderHeader(level int, line string) string {
	text := ""
	if level+1 <= len(line) {
		text = line[level+1:]
	}
	return fmt.Sprintf("<h%d>%s</h%d>", level, text, level)
}

// isListItem reports whether a line is a list item, i.e. it starts with "* ".
func isListItem(line string) bool {
	return strings.HasPrefix(line, "* ")
}

